cat > /tmp/greenmail.js <<'EOF'
var System = java.lang.System;
System.getenv('GREENMAIL_OPTS').trim().split(/\s+/).forEach(
  function (option) {
    var pair = option.replace(/^-D/, '').split('=');
    System.setProperty(pair[0], pair.slice(1).join('='));
  });
function type(name) {
  return Java.type('com.icegreen.greenmail.' + name);
}
var GreenMail = type('util.GreenMail');
java.lang.Thread.currentThread().setContextClassLoader(
  GreenMail.class.getClassLoader());
var properties = System.getProperties();
var setups = new (type('util.PropertiesBasedServerSetupBuilder'))()
  .build(properties);
var configuration = new (type(
  'configuration.PropertiesBasedGreenMailConfigurationBuilder'))()
  .build(properties);
var greenMail = new (Java.extend(GreenMail))(setups, {
  start: function () {
    Java.super(greenMail).start();
    greenMail.getImap().setClientSocketTimeout(30 * 60 * 1000);
    var users = greenMail.getUserManager();
    var deliver = users.getMessageDeliveryHandler();
    users.setMessageDeliveryHandler(function (moving, address) {
      var message = moving.getMessage();
      if (message.getHeader('Message-Id') === null) {
        message.addHeader('Message-Id', '<' + java.util.UUID
          .randomUUID().toString().toUpperCase() +
          '.1@mail.example.com>');
      }
      if (message.getHeader('Date') === null) {
        message.addHeader('Date', new java.text.SimpleDateFormat(
          'EEE, dd MMM yyyy HH:mm:ss Z', java.util.Locale.US)
          .format(new java.util.Date()));
      }
      return deliver.handle(moving, address);
    });
  }
});
greenMail.withConfiguration(configuration).start();
var api = new (type('standalone.GreenMailApiServerBuilder'))()
  .configure(properties);
if (api.isEnabled()) {
  api.withGreenMail(greenMail, setups, configuration).build().start();
}
java.lang.Thread.currentThread().join();
EOF
